//! `init` and `keys`: the real binary, end to end. Keys are generated by the binary at test time in
//! a temporary directory; every command's output is scanned for every secret generated so far, and
//! the documents it writes are read back through the core verifiers a client uses.

mod common;

use std::cell::RefCell;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Output;

use common::*;
use ed25519_dalek::SigningKey;
use ed25519_dalek::pkcs8::DecodePrivateKey;
use lunepack_core::{
    AppId, Clock, ClockReading, RollbackFloor, TrustedRoot, VerifiedKeySet, advance_root,
    verify_key_set,
};
use lunepack_crypto::{Ed25519Verifier, Sha256Hasher};

const APP: &str = "org.example.hello";
const T0: u64 = 1_800_000_000;
const TWO_YEARS: u64 = 63_072_000;

struct At(u64);

impl Clock for At {
    fn now_unix_secs(&self) -> u64 {
        self.0
    }
}

struct Key {
    path: PathBuf,
    public: String,
    id: String,
}

struct World {
    dir: tempfile::TempDir,
    config: PathBuf,
    release: PathBuf,
    secrets: RefCell<Vec<Vec<u8>>>,
}

fn s(path: &Path) -> &str {
    path.to_str().expect("utf-8 path")
}

impl World {
    fn new() -> World {
        let dir = tempfile::tempdir().unwrap();
        let release = dir.path().join("release");
        fs::create_dir(&release).unwrap();
        World {
            config: dir.path().join("lunepack.toml"),
            release,
            dir,
            secrets: RefCell::new(Vec::new()),
        }
    }

    /// Runs the binary and scans its output for every secret generated so far.
    fn cmd(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
        let output = run(args, env);
        let secrets = self.secrets.borrow();
        let refs: Vec<&[u8]> = secrets.iter().map(Vec::as_slice).collect();
        assert_no_secrets(&output, &refs);
        // Values passed in the environment are secrets too.
        let env_values: Vec<&[u8]> = env.iter().map(|(_, v)| v.as_bytes()).collect();
        assert_no_secrets(&output, &env_values);
        output
    }

    /// `lunepack --config <config> <args…>`.
    fn run(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
        let mut full = vec!["--config", s(&self.config)];
        full.extend_from_slice(args);
        self.cmd(&full, env)
    }

    fn new_key(&self, name: &str) -> Key {
        let base = self.dir.path().join(name);
        let out = self.cmd(&["keys", "gen", s(&base)], &[]);
        assert_ok(&out, "keys gen");
        let text = stdout(&out);
        assert_eq!(text.lines().count(), 2, "gen prints two lines: {text:?}");
        let path = base.with_extension("key");
        assert!(path.is_file(), "the extension is added");
        let pem = fs::read_to_string(&path).unwrap();
        let seed = SigningKey::from_pkcs8_pem(&pem).unwrap().to_bytes();
        {
            let mut secrets = self.secrets.borrow_mut();
            secrets.push(pem.into_bytes());
            secrets.push(seed.to_vec());
        }
        Key {
            path,
            public: field(&text, "public:"),
            id: field(&text, "id:"),
        }
    }

    fn init(&self, root_keys: &[&Key], threshold: u64) {
        let t = threshold.to_string();
        let mut args = vec!["init", "--app-id", APP, "--threshold", t.as_str()];
        for k in root_keys {
            args.extend_from_slice(&["--root-key", &k.public]);
        }
        let out = self.run(&args, &[]);
        assert_ok(&out, "init");
    }

    fn set(&self, release_keys: &[&Key], signers: &[String], at: u64, extra: &[&str]) -> Output {
        let epoch = at.to_string();
        let mut args = vec!["keys", "set", "--release-dir", s(&self.release)];
        for k in release_keys {
            args.extend_from_slice(&["--release-key", &k.public]);
        }
        for signer in signers {
            args.extend_from_slice(&["--sign", signer]);
        }
        args.extend_from_slice(extra);
        self.run(&args, &[("SOURCE_DATE_EPOCH", &epoch)])
    }

    fn keys_json(&self) -> Vec<u8> {
        fs::read(self.release.join("keys.json")).expect("keys.json")
    }

    /// The root after walking `root-<k>.json` from a compiled-in root of `keys`, as a client would.
    fn walk(&self, root_keys: &[&Key], threshold: u64) -> TrustedRoot {
        let publics: Vec<[u8; 32]> = root_keys.iter().map(|k| hex(&k.public)).collect();
        let mut root = TrustedRoot::from_parts(
            AppId::parse(APP).unwrap(),
            1,
            threshold,
            &publics,
            &Sha256Hasher,
            &Ed25519Verifier,
        )
        .unwrap();
        loop {
            let path = self
                .release
                .join(format!("root-{}.json", root.version() + 1));
            let Ok(bytes) = fs::read(&path) else { break };
            root = advance_root(&root, &bytes, &Sha256Hasher, &Ed25519Verifier).unwrap();
        }
        root
    }

    fn verified_keys(&self, root: &TrustedRoot, at: u64) -> VerifiedKeySet {
        verify_key_set(
            root,
            &self.keys_json(),
            &RollbackFloor::default(),
            &ClockReading::read(&At(at), None),
            &Sha256Hasher,
            &Ed25519Verifier,
        )
        .expect("keys.json verifies for a client")
    }
}

fn hex(text: &str) -> [u8; 32] {
    let bytes: Vec<u8> = (0..32)
        .map(|i| u8::from_str_radix(&text[2 * i..2 * i + 2], 16).unwrap())
        .collect();
    bytes.try_into().unwrap()
}

fn file(k: &Key) -> String {
    format!("file:{}", s(&k.path))
}

