#[test]
fn gen_init_set_show_round_trip() {
    let w = World::new();
    let root = w.new_key("root");
    let release = w.new_key("release");
    assert_eq!(root.public.len(), 64);
    assert_eq!(root.id.len(), 64);
    assert_ne!(root.public, release.public);

    w.init(&[&root], 1);
    let config = fs::read_to_string(&w.config).unwrap();
    assert!(config.contains(&root.public));
    assert!(config.contains(APP));

    let out = w.set(&[&release], &[file(&root)], T0, &[]);
    assert_ok(&out, "keys set");
    let chain = w.walk(&[&root], 1);
    let keys = w.verified_keys(&chain, T0);
    assert_eq!(keys.version(), 1);
    assert_eq!(keys.root_version(), 1);
    assert_eq!(keys.threshold(), 1);
    assert_eq!(keys.keys().len(), 1);
    assert_eq!(keys.expires(), None);
    // A new key's window is now .. now + two years.
    assert_eq!(
        (keys.windows()[0].not_before, keys.windows()[0].not_after),
        (T0, T0 + TWO_YEARS)
    );

    // `keys show` prints the same two lines `gen` did.
    let show = w.run(&["keys", "show", "--sign", &file(&release)], &[]);
    assert_ok(&show, "keys show");
    let text = stdout(&show);
    assert_eq!(field(&text, "public:"), release.public);
    assert_eq!(field(&text, "id:"), release.id);
    assert_eq!(text.lines().count(), 2);
}

#[test]
fn set_keeps_windows_of_known_keys_and_counts_versions_up() {
    let w = World::new();
    let root = w.new_key("root");
    let (a, b) = (w.new_key("rel-a"), w.new_key("rel-b"));
    w.init(&[&root], 1);

    // The root key comes from an environment variable this time.
    let pem = fs::read_to_string(&root.path).unwrap();
    let env_signer = "env:LUNEPACK_TEST_ROOT_KEY".to_owned();
    let first = w.set(&[&a], &[file(&root)], T0, &[]);
    assert_ok(&first, "first set");

    let epoch = (T0 + 100).to_string();
    let out = w.run(
        &[
            "keys",
            "set",
            "--release-dir",
            s(&w.release),
            "--release-key",
            &a.public,
            "--release-key",
            &b.public,
            "--sign",
            &env_signer,
            "--threshold",
            "2",
            "--expires",
            "1900000000",
        ],
        &[
            ("SOURCE_DATE_EPOCH", &epoch),
            ("LUNEPACK_TEST_ROOT_KEY", &pem),
        ],
    );
    assert_ok(&out, "second set with an env signer");
    let keys = w.verified_keys(&w.walk(&[&root], 1), T0 + 100);
    assert_eq!(keys.version(), 2);
    assert_eq!(keys.threshold(), 2);
    assert_eq!(keys.expires(), Some(1_900_000_000));
    let by_public = |k: &Key| {
        let i = keys
            .keys()
            .keys()
            .iter()
            .position(|r| r.public().as_bytes() == &hex(&k.public))
            .unwrap();
        (keys.windows()[i].not_before, keys.windows()[i].not_after)
    };
    assert_eq!(by_public(&a), (T0, T0 + TWO_YEARS), "A keeps its window");
    assert_eq!(by_public(&b), (T0 + 100, T0 + 100 + TWO_YEARS), "B is new");

    // Explicit bounds apply to every key listed.
    let third = w.set(
        &[&a, &b],
        &[file(&root)],
        T0 + 200,
        &["--not-before", "1700000000", "--not-after", "1950000000"],
    );
    assert_ok(&third, "third set");
    let keys = w.verified_keys(&w.walk(&[&root], 1), T0 + 200);
    assert_eq!(keys.version(), 3);
    assert!(
        keys.windows()
            .iter()
            .all(|x| (x.not_before, x.not_after) == (1_700_000_000, 1_950_000_000))
    );
}

#[test]
fn rotate_root_then_set_again() {
    let w = World::new();
    let (old, new, release) = (
        w.new_key("root-old"),
        w.new_key("root-new"),
        w.new_key("release"),
    );
    w.init(&[&old], 1);
    assert_ok(&w.set(&[&release], &[file(&old)], T0, &[]), "set");

    // Only the old side signed: refused, nothing written.
    let out = w.run(
        &[
            "keys",
            "rotate-root",
            "--release-dir",
            s(&w.release),
            "--new-root-key",
            &new.public,
            "--new-threshold",
            "1",
            "--sign",
            &file(&old),
            "--sign-new",
            &file(&old),
        ],
        &[],
    );
    let err = assert_fails(&out, 1, "rotation without a new-root signer");
    assert!(err.contains("not one of the new root keys"), "{err}");
    assert!(!w.release.join("root-2.json").exists());

    let out = w.run(
        &[
            "keys",
            "rotate-root",
            "--release-dir",
            s(&w.release),
            "--new-root-key",
            &new.public,
            "--new-threshold",
            "1",
            "--sign",
            &file(&old),
            "--sign-new",
            &file(&new),
        ],
        &[],
    );
    assert_ok(&out, "rotate-root");
    assert!(w.release.join("root-2.json").is_file());

    // A client walking from the compiled-in root reaches root 2, and keys.json is re-signed.
    let chain = w.walk(&[&old], 1);
    assert_eq!(chain.version(), 2);
    let keys = w.verified_keys(&chain, T0);
    assert_eq!(keys.version(), 2);
    assert_eq!(keys.root_version(), 2);
    assert_eq!(keys.keys().len(), 1);
    assert_eq!(
        (keys.windows()[0].not_before, keys.windows()[0].not_after),
        (T0, T0 + TWO_YEARS),
        "windows survive the rotation"
    );

    // `keys set` walks to root 2: the new key signs, the old key no longer can.
    assert_ok(
        &w.set(&[&release], &[file(&new)], T0 + 10, &[]),
        "set under root 2",
    );
    let keys = w.verified_keys(&w.walk(&[&old], 1), T0 + 10);
    assert_eq!((keys.version(), keys.root_version()), (3, 2));
    let out = w.set(&[&release], &[file(&old)], T0 + 20, &[]);
    let err = assert_fails(&out, 1, "set with the retired root key");
    assert!(err.contains("not one of the root keys"), "{err}");

    // Rotating again refuses to overwrite a root file that exists, and a key on both sides signs once.
    let out = w.run(
        &[
            "keys",
            "rotate-root",
            "--release-dir",
            s(&w.release),
            "--new-root-key",
            &new.public,
            "--new-root-key",
            &old.public,
            "--new-threshold",
            "2",
            "--sign",
            &file(&new),
            "--sign-new",
            &file(&new),
            "--sign-new",
            &file(&old),
        ],
        &[],
    );
    assert_ok(&out, "rotation with a key on both sides");
    assert_eq!(w.walk(&[&old], 1).version(), 3);
    assert_eq!(w.walk(&[&old], 1).threshold(), 2);
}

#[test]
fn rotation_without_keys_json_writes_only_the_root() {
    let w = World::new();
    let (old, new) = (w.new_key("root-old"), w.new_key("root-new"));
    w.init(&[&old], 1);
    let out = w.run(
        &[
            "keys",
            "rotate-root",
            "--release-dir",
            s(&w.release),
            "--new-root-key",
            &new.public,
            "--new-threshold",
            "1",
            "--sign",
            &file(&old),
            "--sign-new",
            &file(&new),
        ],
        &[],
    );
    assert_ok(&out, "rotate-root");
    assert!(!w.release.join("keys.json").exists());
    assert_eq!(w.walk(&[&old], 1).version(), 2);
}

#[test]
fn keys_json_is_byte_identical_for_the_same_input() {
    let a = World::new();
    let b = World::new();
    // Two worlds, the same keys: copy the key files and config from one to the other.
    let (root, release) = (a.new_key("root"), a.new_key("release"));
    a.init(&[&root], 1);
    assert_ok(&a.set(&[&release], &[file(&root)], T0, &[]), "set a");
    fs::copy(&root.path, b.dir.path().join("root.key")).unwrap();
    fs::copy(&a.config, &b.config).unwrap();
    let copied = Key {
        path: b.dir.path().join("root.key"),
        public: root.public.clone(),
        id: root.id.clone(),
    };
    let out = b.set(&[&release], &[file(&copied)], T0, &[]);
    assert_ok(&out, "set b");
    assert_eq!(a.keys_json(), b.keys_json());
    // Another instant is another document.
    let c = World::new();
    fs::copy(&root.path, c.dir.path().join("root.key")).unwrap();
    fs::copy(&a.config, &c.config).unwrap();
    let moved = Key {
        path: c.dir.path().join("root.key"),
        public: root.public.clone(),
        id: root.id.clone(),
    };
    assert_ok(&c.set(&[&release], &[file(&moved)], T0 + 1, &[]), "set c");
    assert_ne!(a.keys_json(), c.keys_json());
}

#[test]
fn signers_named_in_the_config() {
    let w = World::new();
    let (root, release) = (w.new_key("root"), w.new_key("release"));
    w.init(&[&root], 1);
    // The key file sits next to the config; the command signer's program does not exist.
    let mut config = fs::read_to_string(&w.config).unwrap();
    config.push_str(&format!(
        "\n[signers.root]\nfile = \"root.key\"\n\n[signers.hsm]\ncommand = [\"no-such-signer-program\", \"secret-arg-value\"]\npublic = \"{}\"\n",
        root.public
    ));
    fs::write(&w.config, config).unwrap();

    // Run from another directory: the file is relative to the config, not the cwd.
    let elsewhere = tempfile::tempdir().unwrap();
    let args = [
        "--config",
        s(&w.config),
        "keys",
        "set",
        "--release-dir",
        s(&w.release),
        "--release-key",
        &release.public,
        "--sign",
        "root",
    ];
    let epoch = T0.to_string();
    let out = run_in(
        Some(elsewhere.path()),
        &args,
        &[("SOURCE_DATE_EPOCH", &epoch)],
    );
    assert_ok(&out, "set with a named file signer");

    // A command signer's public key needs no spawn.
    let show = w.run(&["keys", "show", "--sign", "hsm"], &[]);
    assert_ok(&show, "show");
    assert_eq!(field(&stdout(&show), "public:"), root.public);
    // Signing does spawn it: the failure names the program and none of its arguments.
    let out = w.set(&[&release], &["hsm".to_owned()], T0 + 5, &[]);
    let err = assert_fails(&out, 1, "set with a missing command");
    assert!(err.contains("no-such-signer-program"), "{err}");
    assert!(!err.contains("secret-arg-value"), "{err}");

    let out = w.set(&[&release], &["nobody".to_owned()], T0 + 5, &[]);
    let err = assert_fails(&out, 1, "unknown signer name");
    assert!(err.contains("no signer named"), "{err}");
}

#[test]
fn refusals() {
    let w = World::new();
    let (root, other) = (w.new_key("root"), w.new_key("other"));

    // Overwriting a key file or a config.
    let before = fs::read(&root.path).unwrap();
    let base = w.dir.path().join("root");
    let out = w.cmd(&["keys", "gen", s(&base)], &[]);
    let err = assert_fails(&out, 1, "gen over an existing key");
    assert!(err.contains("already exists"), "{err}");
    assert_eq!(fs::read(&root.path).unwrap(), before);

    w.init(&[&root], 1);
    let config_before = fs::read(&w.config).unwrap();
    let out = w.run(&["init", "--app-id", APP, "--root-key", &other.public], &[]);
    let err = assert_fails(&out, 1, "init over an existing config");
    assert!(err.contains("already exists"), "{err}");
    assert_eq!(fs::read(&w.config).unwrap(), config_before);

    // Init validates before writing: threshold above the key count, bad hex, bad app id.
    let fresh = w.dir.path().join("fresh.toml");
    for args in [
        vec![
            "init",
            "--app-id",
            APP,
            "--root-key",
            &root.public,
            "--threshold",
            "2",
        ],
        vec!["init", "--app-id", APP, "--root-key", "NOT-HEX-secret-ish"],
        vec!["init", "--app-id", "Bad App", "--root-key", &root.public],
        vec![
            "init",
            "--app-id",
            APP,
            "--root-key",
            &root.public,
            "--threshold",
            "0",
        ],
    ] {
        let mut full = vec!["--config", s(&fresh)];
        full.extend(args);
        let out = w.cmd(&full, &[]);
        let err = assert_fails(&out, 1, "bad init");
        assert!(!err.contains("NOT-HEX-secret-ish"), "{err}");
        assert!(!fresh.exists(), "nothing written");
    }

    // Usage errors are exit 2.
    for args in [
        vec!["keys", "frobnicate"],
        vec!["keys", "set"],
        vec!["--no-such-flag"],
        vec![],
    ] {
        assert_fails(&w.cmd(&args, &[]), 2, "usage");
    }

    // A release directory that is not one, and unreadable chain files.
    let missing = w.dir.path().join("missing");
    let out = w.run(
        &[
            "keys",
            "set",
            "--release-dir",
            s(&missing),
            "--release-key",
            &other.public,
            "--sign",
            &file(&root),
        ],
        &[],
    );
    assert_fails(&out, 1, "no release dir");
    fs::write(w.release.join("root-2.json"), b"{}").unwrap();
    let out = w.set(&[&other], &[file(&root)], T0, &[]);
    let err = assert_fails(&out, 1, "a root file that does not verify");
    assert!(err.contains("root-2.json"), "{err}");
    fs::remove_file(w.release.join("root-2.json")).unwrap();
    // A gap ends the walk: root-3.json without root-2.json is not read.
    fs::write(w.release.join("root-3.json"), b"{}").unwrap();
    assert_ok(&w.set(&[&other], &[file(&root)], T0, &[]), "set past a gap");
    // A corrupt keys.json is never silently replaced.
    fs::write(w.release.join("keys.json"), b"not a document").unwrap();
    let out = w.set(&[&other], &[file(&root)], T0, &[]);
    let err = assert_fails(&out, 1, "corrupt keys.json");
    assert!(err.contains("keys.json"), "{err}");
}

#[test]
fn too_few_root_signers_is_refused_before_signing() {
    let w = World::new();
    let (r1, r2, rel) = (
        w.new_key("root-1"),
        w.new_key("root-2"),
        w.new_key("release"),
    );
    w.init(&[&r1, &r2], 2);
    let out = w.set(&[&rel], &[file(&r1)], T0, &[]);
    let err = assert_fails(&out, 1, "one of two root signers");
    assert!(err.contains("needs 2"), "{err}");
    assert!(!w.release.join("keys.json").exists());
    // The same key twice is one signer.
    let out = w.set(&[&rel], &[file(&r1), file(&r1)], T0, &[]);
    assert_fails(&out, 1, "the same root signer twice");
    // A key that is not a root key.
    let out = w.set(&[&rel], &[file(&r1), file(&rel)], T0, &[]);
    assert_fails(&out, 1, "a non-root signer");
    // Both: fine.
    assert_ok(
        &w.set(&[&rel], &[file(&r1), file(&r2)], T0, &[]),
        "two signers",
    );
    assert_eq!(w.verified_keys(&w.walk(&[&r1, &r2], 2), T0).version(), 1);
}

#[test]
fn a_bad_source_date_epoch_fails_and_is_not_echoed() {
    let w = World::new();
    let (root, rel) = (w.new_key("root"), w.new_key("release"));
    w.init(&[&root], 1);
    for bad in [
        "",
        "notanumber77",
        "1.5e9x",
        "-1771771771",
        "+1771771771",
        "\u{ff19}\u{ff19}\u{ff19}",
        "9007199254740993",
        "0x1f2e3d",
        "18446744073709551616",
    ] {
        let out = w.set_raw(&rel, &root, bad);
        let err = assert_fails(&out, 1, "bad SOURCE_DATE_EPOCH");
        assert!(err.contains("SOURCE_DATE_EPOCH"), "{err}");
        if !bad.is_empty() {
            assert!(!err.contains(bad), "the value is echoed: {err}");
        }
        assert!(!w.release.join("keys.json").exists());
    }
    assert_ok(
        &w.set(&[&rel], &[file(&root)], 0, &[]),
        "epoch 0 is a valid instant",
    );
}

impl World {
    fn set_raw(&self, rel: &Key, root: &Key, epoch: &str) -> Output {
        self.run(
            &[
                "keys",
                "set",
                "--release-dir",
                s(&self.release),
                "--release-key",
                &rel.public,
                "--sign",
                &file(root),
            ],
            &[("SOURCE_DATE_EPOCH", epoch)],
        )
    }
}

#[test]
fn config_errors_name_the_line_and_never_echo_it() {
    let w = World::new();
    let root = w.new_key("root");
    let config = |body: &str| {
        let text = format!(
            "app_id = \"{APP}\"\n\n[root]\nthreshold = 1\nkeys = [\"{}\"]\n{body}",
            root.public
        );
        fs::write(&w.config, text).unwrap();
    };
    let show = || w.run(&["keys", "show", "--sign", &file(&root)], &[]);
    // `--sign file:` needs no config; use a named signer to force reading it.
    let named = || w.run(&["keys", "show", "--sign", "whoever"], &[]);

    // An unknown field: line 6, the key is named, its value is not.
    config("bogus = \"SECRETVALUE-xyz\"\n");
    let err = assert_fails(&named(), 1, "unknown field");
    assert!(err.contains("line 6"), "{err}");
    assert!(err.contains("unknown field"), "{err}");
    assert!(!err.contains("SECRETVALUE"), "{err}");

    // A value of the wrong type is reported without the value.
    config("version = \"SECRETVALUE-xyz\"\n");
    let err = assert_fails(&named(), 1, "wrong type");
    assert!(err.contains("line 6"), "{err}");
    assert!(!err.contains("SECRETVALUE"), "{err}");

    // Broken syntax.
    config("this is = = not toml SECRETVALUE\n");
    let err = assert_fails(&named(), 1, "syntax");
    assert!(err.contains("line 6"), "{err}");
    assert!(!err.contains("SECRETVALUE"), "{err}");

    // A signer with two forms, a command without a public key, a bad public key.
    config("");
    let mut text = fs::read_to_string(&w.config).unwrap();
    for (extra, expect) in [
        ("[signers.x]\nfile = \"a\"\nenv = \"B\"\n", "exactly one"),
        ("[signers.x]\ncommand = [\"prog\"]\n", "needs `public`"),
        (
            "[signers.x]\nfile = \"a\"\npublic = \"00\"\n",
            "exactly one",
        ),
        (
            "[signers.x]\ncommand = [\"prog\"]\npublic = \"zz-SECRETVALUE\"\n",
            "64 lowercase hex",
        ),
        (
            "[signers.x]\ncommand = []\npublic = \"00\"\n",
            "command is empty",
        ),
    ] {
        let original = text.clone();
        text.push_str(extra);
        fs::write(&w.config, &text).unwrap();
        let err = assert_fails(&named(), 1, expect);
        assert!(err.contains(expect), "{expect}: {err}");
        assert!(!err.contains("SECRETVALUE"), "{err}");
        text = original;
    }

    // A bad root key in the config.
    fs::write(
        &w.config,
        format!("app_id = \"{APP}\"\n\n[root]\nthreshold = 1\nkeys = [\"SECRETVALUE\"]\n"),
    )
    .unwrap();
    let err = assert_fails(&named(), 1, "bad root key");
    assert!(!err.contains("SECRETVALUE"), "{err}");

    // A missing config.
    fs::remove_file(&w.config).unwrap();
    assert_fails(&named(), 1, "no config");
    let _ = show;
}

#[cfg(unix)]
#[test]
fn a_world_readable_key_file_is_refused() {
    use std::os::unix::fs::PermissionsExt;
    let w = World::new();
    let key = w.new_key("root");
    fs::set_permissions(&key.path, fs::Permissions::from_mode(0o644)).unwrap();
    let out = w.cmd(&["keys", "show", "--sign", &file(&key)], &[]);
    let err = assert_fails(&out, 1, "a 0644 key file");
    assert!(err.contains("chmod 600"), "{err}");
    assert!(
        err.contains(key.path.file_name().unwrap().to_str().unwrap()),
        "{err}"
    );
}

#[test]
fn an_env_signer_that_is_unset_is_named_but_not_valued() {
    let w = World::new();
    let out = w.cmd(
        &["keys", "show", "--sign", "env:LUNEPACK_TEST_SURELY_UNSET"],
        &[],
    );
    let err = assert_fails(&out, 1, "unset variable");
    assert!(err.contains("LUNEPACK_TEST_SURELY_UNSET"), "{err}");
    let out = w.cmd(
        &["keys", "show", "--sign", "env:LUNEPACK_TEST_BAD_VALUE"],
        &[("LUNEPACK_TEST_BAD_VALUE", "SECRETVALUE-not-a-pem")],
    );
    let err = assert_fails(&out, 1, "garbage in the variable");
    assert!(err.contains("LUNEPACK_TEST_BAD_VALUE"), "{err}");
    assert!(!err.contains("SECRETVALUE"), "{err}");
}
